package com.shopsphere;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public interface CartRepository{Optional<Cart>find(UUID user);Cart save(Cart c);void delete(UUID user);class InMemory implements CartRepository{private final Map<UUID,Cart>data=new ConcurrentHashMap<>();public Optional<Cart>find(UUID u){return Optional.ofNullable(data.get(u));}public Cart save(Cart c){data.put(c.userId(),c);return c;}public void delete(UUID u){data.remove(u);}}}
